css:
/* From Uiverse.io by Gautammsharma - Tags: clean, material design, minimalist, input, search, glow */
.__UIV_SCOPE__ .input__container--variant {
  background: linear-gradient(to bottom, #F3FFF9, #F3FFF9);
  border-radius: 30px;
  max-width: 13em;
  padding: 1em 1em;
}

.__UIV_SCOPE__ .shadow__input--variant {
  filter: blur(25px);
  border-radius: 30px;
  background-color: #F3FFF9;
  opacity: 0.5;
}

.__UIV_SCOPE__ .input__button__shadow--variant {
  border-radius: 15px;
  background-color: #07372C;
  padding: 10px;
  border: none;
}

.__UIV_SCOPE__ .input__button__shadow--variant:hover {
  background-color: #3C6659;
}

.__UIV_SCOPE__ .input__search--variant {
  width: 13em;
  align-items: center;
  border-radius: 13em;
  outline: none;
  border: none;
  padding: 0.8em;
  font-size: 1.2em;
  color: #002019;
  background-color: transparent;
}

.__UIV_SCOPE__ .input__search--variant::placeholder {
  color: #002019;
  opacity: 0.7;
}

.__UIV_SCOPE__ .input__container--variant {
  background: linear-gradient(to bottom, #F3FFF9, #F3FFF9);
  border-radius: 1.5em;
  max-width: 14em;
  padding: 1em;
  box-shadow: 0em 1em 3em #beecdc64;
}
